import React from "react";
import Grid from "@material-ui/core/Grid";
import "../assets/css/titleBar.css";

function TitleBar(props) {
  return (
    <Grid
      container
      direction="column"
      justify="center"
      alignItems="center"
      id="headerWrapper"
      style={{ marginTop: "2vw" }}
    >
      <Grid
        item
        container
        direction="row"
        justify="space-between"
        alignItems="center"
      >
        <div item="true" className="buttonItemWrapper">
          <button
            className="buttonsButton like-link homeButton hover-underline"
            href="/"
          >
            <h1 className="montserrat-medium fs-2rem">home</h1>
          </button>
        </div>
        <div item="true" className="buttonItemWrapper">
          <button
            className="buttonsButton like-link backButton hover-underline"
            onClick={() => console.log(window.history.back(-1))}
            href="#"
          >
            <h1 className="montserrat-medium fs-2rem">back</h1>
          </button>
        </div>
      </Grid>
      {props.title ? (
        <h1 item="true" id="title" className="montserrat-medium">
          {props.title}
        </h1>
      ) : null}
    </Grid>
  );
  // return (
  //   <div>
  //     <div className="row headerWrapper">
  //       <div className="col-auto text-center">
  //
  //       </div>
  //       <div className="col no-margin no-padding"></div>
  //       <div className="col-auto text-center no-padding">

  //       </div>
  //     </div>
  //     <div className="row no-margin no-padding">
  //       <div className="col text-center">
  //
  //       </div>
  //     </div>
  //   </div>
  // );
}

export default TitleBar;
